contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool approvedBefore, bool wasFraud) public payable {
        require(msg.sender != address(0));
        require(!approvedBefore);

        bool callerApprovedBefore = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        bool retFunded = c.logFunded(); if (__ESBMC_reverted()) return;
        bool retCourtesy = c.logCourtesyCalled(); if (__ESBMC_reverted()) return;
        bool retStartedLiq = c.logStartedLiquidation(wasFraud); if (__ESBMC_reverted()) return;
        bool retExited = c.logExitedCourtesyCall(); if (__ESBMC_reverted()) return;

        bool callerApprovedAfter = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        assert(!retFunded && !retCourtesy && !retStartedLiq && !retExited && !callerApprovedAfter);
    }

    receive() external payable {}
}

