contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bool approvedBefore, bool wasFraud) internal {
        vm.assume(msg.sender != address(0));
        vm.assume(!approvedBefore);
        bool callerApprovedBefore;
        try c.approvedToLog(address(this)) returns (bool __r) { callerApprovedBefore = __r; } catch { return; }
        bool retFunded;
        try c.logFunded() returns (bool __r) { retFunded = __r; } catch { return; }
        bool retCourtesy;
        try c.logCourtesyCalled() returns (bool __r) { retCourtesy = __r; } catch { return; }
        bool retStartedLiq;
        try c.logStartedLiquidation(wasFraud) returns (bool __r) { retStartedLiq = __r; } catch { return; }
        bool retExited;
        try c.logExitedCourtesyCall() returns (bool __r) { retExited = __r; } catch { return; }
        bool callerApprovedAfter;
        try c.approvedToLog(address(this)) returns (bool __r) { callerApprovedAfter = __r; } catch { return; }
        assertTrue(!retFunded && !retCourtesy && !retStartedLiq && !retExited && !callerApprovedAfter);
    }

    function testFuzz_run(bool approvedBefore, bool wasFraud) public {
        _run(approvedBefore, wasFraud);
    }

    receive() external payable {}
